window.registerChapter({"num": 87, "title": "Meningococcal Infections", "group": "Bacterial infections", "pdf_start": 569, "pdf_end": 586, "printed_start": 555, "printed_end": 572, "features": ["Fever", "Petechiae / purpura", "Maculopapular rash", "Conjunctivitis", "Pneumonia", "Meningitis", "Arthritis / bone pain", "Sepsis / shock", "Cytopenia"], "pillars": [{"label": "Etiology and transmission", "text": "N meningitidis is a gram-negative diplococcus with 12 confirmed serogroups based on capsular type.", "pdf_page": 569, "printed_page": 555}, {"label": "Clinical recognition", "text": "Invasive meningococcal infection usually results in septicemia (35%–40% of cases), meningitis (~50% of cases), or both. Bacteremic pneumonia is less common (10% of cases).", "pdf_page": 569, "printed_page": 555}, {"label": "Diagnostic workup", "text": "Cultures of blood and cerebrospinal fluid (CSF) are indicated for patients with suspected invasive meningococcal disease. Cultures of a petechial or purpuric lesion scraping, synovial fluid, and other usually sterile body fluid specimens sometimes are positive.", "pdf_page": 570, "printed_page": 556}, {"label": "Treatment in the atlas", "text": "The priority in management of meningococcal disease is treatment of shock in meningococcemia and of raised intracranial pressure in severe meningitis. Empirical therapy for suspected meningococcal disease should include cefotaxime or ceftriaxone.", "pdf_page": 570, "printed_page": 556}, {"label": "Prevention and infection control", "text": "In addition to standard precautions, droplet precautions are recommended until 24 hours after initiation of effective antimicrobial therapy.", "pdf_page": 571, "printed_page": 557}], "figures": [{"path": "figures/ch087_p0580_01.jpg", "caption": "Image 87.1 Young boy with meningococcemia that demonstrates striking involvement of the extremities with sparing of the trunk. Copyright Martin G. Myers, MD.", "caption_matched": true, "pdf_page": 580, "printed_page": 566, "chapter": 87}, {"path": "figures/ch087_p0580_02.jpg", "caption": "Image 87.2 The arm of the boy shown in Image 87.1, which demonstrates striking extremity involvement and characteristic angular lesions. Copyright Martin G. Myers, MD.", "caption_matched": true, "pdf_page": 580, "printed_page": 566, "chapter": 87}, {"path": "figures/ch087_p0580_03.jpg", "caption": "Image 87.3 Meningococcemia showing striking involvement of the extremities with relative sparing of the skin of the child’s body surface.", "caption_matched": true, "pdf_page": 580, "printed_page": 566, "chapter": 87}, {"path": "figures/ch087_p0580_04.jpg", "caption": "Image 87.4 Meningococcemia. This image shows the lower extremities of the patient in Image 87.3.", "caption_matched": true, "pdf_page": 580, "printed_page": 566, "chapter": 87}, {"path": "figures/ch087_p0581_01.jpg", "caption": "Image 87.5 Papular skin lesions of early meningococcemia.", "caption_matched": true, "pdf_page": 581, "printed_page": 567, "chapter": 87}, {"path": "figures/ch087_p0581_02.jpg", "caption": "Image 87.6 Characteristic, angular, necrotic lesions on the foot of an infant boy with meningococcemia (after 2 days of intravenous penicillin treatment).", "caption_matched": true, "pdf_page": 581, "printed_page": 567, "chapter": 87}, {"path": "figures/ch087_p0581_03.jpg", "caption": "Image 87.7 Preschool-aged girl with meningococcal panophthalmitis. An infant sibling had meningococcal meningitis 1 week before the onset of this child’s illness.", "caption_matched": true, "pdf_page": 581, "printed_page": 567, "chapter": 87}, {"path": "figures/ch087_p0581_04.jpg", "caption": "Image 87.8 Meningococcemia in an adolescent girl with disseminated intravascular coagulation.", "caption_matched": true, "pdf_page": 581, "printed_page": 567, "chapter": 87}, {"path": "figures/ch087_p0581_05.jpg", "caption": "Image 87.9 Meningococcemia in the same patient as in Image 87.8.", "caption_matched": true, "pdf_page": 581, "printed_page": 567, "chapter": 87}, {"path": "figures/ch087_p0582_01.jpg", "caption": "Image 87.11 Gangrene of the toes in the patient shown in Images 87.8–87.10.", "caption_matched": true, "pdf_page": 582, "printed_page": 568, "chapter": 87}, {"path": "figures/ch087_p0582_02.jpg", "caption": "Image 87.12 Cutaneous necrosis in the patient shown in Images 87.8–87.11.", "caption_matched": true, "pdf_page": 582, "printed_page": 568, "chapter": 87}, {"path": "figures/ch087_p0582_03.jpg", "caption": "Image 87.13 A 2-year-old boy with acute meningococcemia with septic shock and purpura fulminans. Courtesy of George Nankervis, MD.", "caption_matched": true, "pdf_page": 582, "printed_page": 568, "chapter": 87}, {"path": "figures/ch087_p0582_04.jpg", "caption": "Image 87.10 Marked purpura of the left foot in the patient shown in Images 87.8 and 87.9.", "caption_matched": true, "pdf_page": 582, "printed_page": 568, "chapter": 87}, {"path": "figures/ch087_p0583_01.jpg", "caption": "Image 87.14 Hemorrhagic adrenal glands from the 2-year-old child in Image 87.13, who had the characteristic histopathologic features of Waterhouse-Friderichsen syndrome at autopsy. Courtesy of George Nankervis, MD.", "caption_matched": true, "pdf_page": 583, "printed_page": 569, "chapter": 87}, {"path": "figures/ch087_p0583_02.jpg", "caption": "Image 87.15 Adrenal hemorrhage in a patient with gram-negative sepsis, a major complication of meningococcal disease with increased mortality. Courtesy of Dimitris P. Agamanolis, MD.", "caption_matched": true, "pdf_page": 583, "printed_page": 569, "chapter": 87}, {"path": "figures/ch087_p0583_03.jpg", "caption": "Image 87.16 Fatal meningococcal meningitis with purulent exudate in the subarachnoid space covering the cerebral convexities. Courtesy of Dimitris P. Agamanolis, MD.", "caption_matched": true, "pdf_page": 583, "printed_page": 569, "chapter": 87}, {"path": "figures/ch087_p0584_01.jpg", "caption": "Image 87.17 Suppurative meningococcal meningitis. The subarachnoid space is filled with neutrophils. Courtesy of Dimitris P. Agamanolis, MD.", "caption_matched": true, "pdf_page": 584, "printed_page": 570, "chapter": 87}, {"path": "figures/ch087_p0584_02.jpg", "caption": "Image 87.18 Petechial rash with a necrotic lesion over the right buttock of an infant girl with Neisseria meningitidis septicemia and meningitis. Courtesy of Ed Fajardo, MD.", "caption_matched": true, "pdf_page": 584, "printed_page": 570, "chapter": 87}, {"path": "figures/ch087_p0584_03.jpg", "caption": "Image 87.19 This micrograph depicts the presence of aerobic gram-negative Neisseria meningitidis diplococcal bacteria (magnification 31,150). Meningococcal disease is an infection caused by a bacterium called N meningitidis or meningococcus. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 584, "printed_page": 570, "chapter": 87}, {"path": "figures/ch087_p0585_01.jpg", "caption": "Image 87.21 Incidence rates (per 100,000 people) of meningococcal disease caused by serogroup B compared with those of serogroups C, W, and Y by age group from 2012 to 2021. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 585, "printed_page": 571, "chapter": 87}, {"path": "figures/ch087_p0585_02.jpg", "caption": "Image 87.20 Incidence rates (per 100,000 people) of meningococcal disease in the United States by year from 1970 to 2019. The incidence rate began decreasing in 1995 and has remained low in 2019. Courtesy of Centers for Disease Control and Prevention.", "caption_matched": true, "pdf_page": 585, "printed_page": 571, "chapter": 87}, {"path": "figures/ch087_p0586_01.jpg", "caption": "Image 87.22 Neisseria meningitidis on chocolate agar. Isolation of this species requires chocolate or Thayer-Martin agar. Colonies are gray-brown and can appear moist to mucoid or dry. N meningitidis can be distinguished from Neisseria gonorrhoeae by the fact that it ferments glucose and maltose. Courtesy of Julia Rosebush, DO; Robert Jerris, PhD; and Theresa Stanley, M(ASCP).", "caption_matched": true, "pdf_page": 586, "printed_page": 572, "chapter": 87}], "tables": [{"pdf_page": 573, "printed_page": 559, "markdown": "|Age of Infants,<br>Children,<br>and Adults|Dose|Duration|Effectiveness, %|Cautions|\n|---|---|---|---|---|\n|**Rifampinª**|**Rifampinª**|**Rifampinª**|**Rifampinª**|**Rifampinª**|\n|<1 mo|5 mg/kg per dose,<br>orally, every 12 h|2 days||Discussion with an expert<br>for infants <1 mo|\n|≥1 mo|10 mg/kg per dose<br>(maximum 600 mg),<br>orally, every 12 h|2 days|90–95|Can interfere with effective-<br>ness of oral contraceptives<br>and some seizure and anti-<br>coagulant medications; can<br>stain soft contact lenses|\n|**Ceftriaxone**|**Ceftriaxone**|**Ceftriaxone**|**Ceftriaxone**|**Ceftriaxone**|\n|<15 y|125 mg, intramuscularly|Single dose|90–95|To decrease pain at injection<br>site, dilute with 1% lidocaine|\n|≥15 y|250 mg, intramuscularly|Single dose|90–95|To decrease pain at injection<br>site, dilute with 1% lidocaine|\n|**Ciproﬂoxacina,b**|**Ciproﬂoxacina,b**|**Ciproﬂoxacina,b**|**Ciproﬂoxacina,b**|**Ciproﬂoxacina,b**|\n|≥1 mo|20 mg/kg (maximum<br>500 mg), orally|Single dose|90–95||\n|Azithromycin|10 mg/kg (maximum<br>500 mg)|Single dose|90|Notrecommended routinely;<br>equivalent to rifampin for<br>eradication of_Neisseria_<br>_meningitidis_ from nasophar-<br>ynx in one study of young<br>adults|\n\n", "path": "tables/ch087_p0573_1.jpg", "orientation_normalized": false}, {"pdf_page": 574, "printed_page": 560, "markdown": "|Age|Vaccine|Status|\n|---|---|---|\n|**Meningococcal ACWY Vaccines**|**Meningococcal ACWY Vaccines**|**Meningococcal ACWY Vaccines**|\n|2 mo through 10 y|MenACWY-Db<br>(Menactra)<br>or<br>MenACWY-CRMc<br>(Menveo)<br>or<br>MenACWY-TTd<br>(MenQuadf)|**Not routinely recommended;**<br>see Table 87.6 for recommendations for people at increased risk|\n|11 through 21 y|MenACWY-D<br>or<br>MenACWY-CRM<br>or<br>MenACWY-TT|•  11 through 18 y of age, with frst dose at age 11–12 y and<br>booster dose at age 16 y (give booster only if frst dose<br>administered prior to 16th birthday)<br>•  19 through 21 y of age, not routinely recommended but may<br>be administered as catch-up immunization for those who<br>have not received a dose after their 16th birthday or who<br>become at increased risk for meningococcal disease|\n|**Meningococcal B Vaccines**|**Meningococcal B Vaccines**|**Meningococcal B Vaccines**|\n|10 y through 15 y|MenB-FHbpe<br>(Trumenba)<br>or<br>MenB-4Cf<br>(Bexsero)|**Not routinely recommended;**<br>see Table 87.6 for recommendations for people at increased risk|\n|16 y through 23 y|MenB-FHbp<br>or<br>MenB-4C|•  Administer based on shared clinical decision-making with<br>preferred age of 16 y through 18 y and 2-dose series<br>recommended<br>•  For MenB-4C (Bexsero), dose 1 administered initially, then<br>followed by dose 2 administered1 month later<br>•  For MenB-FHbp (Trumenba), dose 1 administered initially,<br>then followed by dose 2 administered 6 months later; in<br>setting of serogroup B meningococcal outbreak, a 3-dose<br>vaccine series administered at 0, 1–2, and 6 months<br>See Table 87.6 for recommendations forpeople at increased risk|\n|**Meningococcal ABCWY Vaccine**|**Meningococcal ABCWY Vaccine**|**Meningococcal ABCWY Vaccine**|\n|10 through 25 y|MenABCWYg|May be used when both MenACWY and MenB are indicated at<br>the same visith|\n\n", "path": "tables/ch087_p0574_1.jpg", "orientation_normalized": false}, {"pdf_page": 575, "printed_page": 561, "markdown": "|Age|Subgroup|Primary Immunization|Booster Dose|\n|---|---|---|---|\n|**Meningococcal ACWY Vaccines**|**Meningococcal ACWY Vaccines**|**Meningococcal ACWY Vaccines**|**Meningococcal ACWY Vaccines**|\n|2 through<br>23 mo of age|Children who:<br>•  have persistent complement defciencies<br>(including complement inhibitor use)<br>•  have functional or anatomic asplenia<br>•  have HIV infection<br>•  travel to or are residents of countries where<br>meningococcal disease is hyperendemic or<br>epidemic<br>•  are at risk during a community outbreak<br>attributable to an A,C,W,Y vaccine serogroup|**MenACWY-CRM (Menveo):** 4 doses at 2, 4, 6, and 12 mo<br>In children initiating vaccination at 7 through 23 mo of age,<br>MenACWY-CRM is to be administered as a 2-dose series, with<br>the second dose administered in the second year of life and at<br>least 3 mo after the frst dose<br>**MenACWY-D (Menactra):** MenACWY-D SHOULD NOT<br>BE USED before 2 y of age in children with asplenia or HIV to<br>avoid interference with the immune response to the pneumo-<br>coccal conjugate vaccine (PCV) series<br>For children aged9 mo who are at increased risk because of<br>complement defciency, travel or an outbreak, MenACWY-D<br>can be administered as a 2-dose series at 9 and 12 months<br>(3 months apart; may be administered8 weeks apart in<br>travelers)<br>**MenACWY-TT (MenQuadf):** SHOULD NOT BE USED<br>before 2y of age because not approved in this age group|Person remains at increased risk and frst<br>dose received at age:<br>• ** 2 mo through 6 y of age:** Should receive<br>additional dose of MenACWY 3 y after primary<br>immunization. Boosters should be repeated<br>every 5 y.d|\n|2 yf|People who:<br>•  have persistent complement defciencies<br>•  have functional or anatomic asplenia<br>•  have HIV infection|2 doses of either**MenACWY-CRM** or**MenACWY-D**e or<br>**MenACWY-TT**, 8–12 wk apart<br>**MenACWY-D** (Menactra) may be used if at least 4 wk after<br>completion of PCV doses|• ** 2 y through 6 y of age:** Should receive addi-<br>tional dose of MenACWY 3 y after primary<br>immunization. Boosters should be repeated<br>every 5 y.d<br>•  7 y of age: Should receive an additional<br>dose of MenACWY 5 y after primary immuniza-<br>tion. Boosters should be repeated every<br>5 y.d|\n\n", "path": "tables/ch087_p0575_1.jpg", "orientation_normalized": true}, {"pdf_page": 576, "printed_page": 562, "markdown": "|Age|Subgroup|Primary Immunization|Booster Dose|\n|---|---|---|---|\n|**Meningococcal ACWY Vaccines**_(continued)_|**Meningococcal ACWY Vaccines**_(continued)_|**Meningococcal ACWY Vaccines**_(continued)_|**Meningococcal ACWY Vaccines**_(continued)_|\n|2 yf|People who:<br>•  are at risk during a community outbreak<br>attributable to an A,C,W,Y vaccine serogroup<br>•  travel to or are residents of countries<br>where meningococcal disease is hyper-<br>endemic or epidemic<br>•  college freshmen living in residence<br>halls and military recruits<br>•  are laboratory workers routinely exposed<br>to isolates of_Neisseria meningitidis_|1 dose of**MenACWY-CRM** or**MenACWY-D**e or<br>**MenACWY-TT**||\n|**Meningococcal B Vaccines**|**Meningococcal B Vaccines**|**Meningococcal B Vaccines**|**Meningococcal B Vaccines**|\n|10 yg|People who:<br>•  have persistent complement defciencies<br>(including complement inhibitor use)<br>•  have functional or anatomic asplenia<br>•  are laboratory workers routinely exposed<br>to isolates of_N meningitidis_<br>•  are at increased risk, as determined by<br>public health offcials, because of a<br>serogroup B meningococcal disease<br>outbreak|2-dose series of**MenB-4C**, 1 mo apart<br>OR<br>3-dose series of**MenB-FHbp**, with 2**nd** and 3**rd** doses<br>administered 1–2 and 6 mo after initial doses|**For subgroup at increased risk:**<br>• ** Other than outbreak: booster**g **1 year**<br>**following completion of a MenB**<br>**primary series followed by MenB**<br>**booster every 2–3 years thereafter.**d<br>• ** For outbreak: booster**h **if it has been**<br>**1 year since completion of a MenB**<br>**primary series** **(****6 months interval**<br>**might also be considered by public**<br>**health offcials).**|\n\n", "path": "tables/ch087_p0576_1.jpg", "orientation_normalized": true}], "reader_html": "<section><h2>Clinical Manifestations</h2><p>Invasive meningococcal infection usually results in septicemia (35%–40% of cases), meningitis (~50% of cases), or both. Bacteremic pneumonia is less common (10% of cases). Rarely, Neisseria meningitidis is identified as a cause of occult bacteremia. The onset of invasive infections can be insidious and nonspecific, but the onset of septicemia (meningococcemia) typically is abrupt, with fever, chills, malaise, myalgia, limb pain, prostration, and a rash that initially can be macular or maculopapular but typically becomes petechial or purpuric within hours. A similar rash can occur with viral infections or with severe sepsis attributable to other bacterial pathogens. In fulminant cases, purpura, limb ischemia, coagulopathy, pulmonary edema, shock, coma, and death can ensue within hours despite appropriate management. Signs and symptoms of meningococcal meningitis are indistinguishable from those associated with pneumococcal meningitis. In severe and fatal cases of meningococcal meningitis, increased intracranial pressure is a predominant presenting feature. Invasive infections can be complicated by arthritis, myocarditis, pericarditis, and endophthalmitis. Noninvasive meningococcal infections, such as conjunctivitis and urethritis, also occur. Chronic meningococcemia is a rare syndrome, mostly seen in young adults, that is characterized by a more prolonged course (&gt;7 days) with intermittent fever, migratory arthralgia, and cutaneous lesions (erythematous macules, papules, nodules, petechiae, or purpura).</p><small class='source'>Printed p. 555 · PDF p. 569</small><p>The overall case fatality rate for invasive meningococcal disease is 15% and is somewhat higher in older adults. Clinical predictors of mortality include coma, hypotension, leukopenia, and thrombocytopenia. A self-limiting postinfectious inflammatory syndrome occurs in fewer than 10% of cases, begins a minimum 4 days after onset of meningococcal infection, and most commonly presents as fever and arthritis or vasculitis with less common manifestations including iritis, scleritis, conjunctivitis, pericarditis, and polyserositis.</p><small class='source'>Printed p. 555 · PDF p. 569</small><p>Sequelae associated with meningococcal disease occur in up to 20% of survivors and include hearing loss, neurologic disability, digit or limb amputations, and skin scarring. In addition, patients may experience subtle long-term neurologic deficits, such as impaired school performance, behavioral problems, and attention-deficit/ hyperactivity disorder.</p><small class='source'>Printed p. 555 · PDF p. 569</small></section><section><h2>Etiology</h2><p>N meningitidis is a gram-negative diplococcus with 12 confirmed serogroups based on capsular type.</p><small class='source'>Printed p. 555 · PDF p. 569</small></section><section><h2>Epidemiology</h2><p>N meningitidis disease rates are highest in infants &lt;1 year of age, followed by children 1 to 4 years of age, the very elderly (≥85 years), and adolescents and young adults 16 to 23 years of age. Household contacts of cases have 500 to 800 times the rate of disease of the general population. A predominance of U.S. cases is observed in the winter, often noted 2 to 3 weeks following onset of influenza outbreaks, with a peak of cases in January, February, and March. Patients with persistent complement-component deficiencies (eg, C3, C5–C9, properdin, or factor D or factor H deficiencies), with anatomic or functional asplenia or HIV infection, or treated with eculizumab or similar complement inhibitors are at increased risk of invasive and recurrent meningococcal disease. Asymptomatic colonization of the upper respiratory tract is most common in older adolescents and young adults and is the reservoir from which the organism is spread. Transmission occurs from person to person through droplets from the respiratory tract and requires close contact. Patients should be considered capable of transmitting the organism for up to 24 hours after initiation of effective antimicrobial treatment.</p><small class='source'>Printed p. 555 · PDF p. 569</small><p>Distribution of meningococcal serogroups in the United States has shifted in the past 2 decades. Serogroup B accounts for most cases currently, followed by serogroups C, W, and Y and nongroupable (nonencapsulated) meningococci. Serogroup distribution varies by age, location, and time. In infants and children younger than 60 months, approximately two-thirds of cases are caused by serogroup B. More than 75% of cases among adolescents and young adults are caused by serogroups B, C, Y, or W and, therefore, potentially are preventable with available vaccines.</p><small class='source'>Printed p. 555 · PDF p. 569</small><p>Since the early 2000s, annual incidence rates for invasive meningococcal disease have decreased, and during 2019 approximately 375 cases occurred (incidence of 0.11 per 100,000 population) in the United States. The decrease in cases in the United States started before the 2005 introduction of ACWY meningococcal conjugate vaccine into the routine immunization schedule at age 11 through 12 years and the 2010 recommendation for a booster vaccine at age 16 years. Reasons for this decrease in incidence are postulated to be related to the increased use of influenza vaccine, reduction in the carriage rates, the use of meningococcal conjugate vaccines in preadolescents and adolescents, and changes in behavioral risk factors (eg, decreases in smoking and exposure to secondhand smoke among adolescents and young adults).</p><small class='source'>Printed p. 556 · PDF p. 570</small><p>Strains belonging to groups A, B, C, W, X, and Y are implicated most commonly in invasive disease worldwide. Serogroup A has historically been associated with epidemics outside the United States, primarily in sub-Saharan Africa. A serogroup A meningococcal conjugate vaccine was introduced in the “meningitis belt” of sub-Saharan Africa starting in December 2010, and its widespread use has been associated with a marked reduction in serogroup A disease rates; recent outbreaks in the meningitis belt have been associated with serogroups C, W, and X. In Europe, Australia, and South America, the incidence of meningococcal disease ranged from 0.3 to 2 cases per 100,000 population in recent years. Serogroups B, C, W, and Y are most commonly reported in these regions. Rates of meningococcal disease declined globally (~70%) in 2020 during the COVID-19 pandemic; these declines may have been the result of masking, social distancing, and other measures controlling respiratory droplet spread.</p><small class='source'>Printed p. 556 · PDF p. 570</small><p>Most cases of meningococcal disease are sporadic, with fewer than 10% associated with outbreaks. Outbreaks occur in communities and institutions, including child care centers, schools, colleges, and military recruit camps. Multiple outbreaks of serogroup B meningococcal disease have occurred on college campuses, and outbreaks of serogroup C meningococcal disease have been reported among men who have sex with men and among people lacking housing.</p><small class='source'>Printed p. 556 · PDF p. 570</small><p>The incubation period for invasive disease is 1 to 10 days, usually less than 4 days.</p><small class='source'>Printed p. 556 · PDF p. 570</small></section><section><h2>Diagnostic Tests</h2><p>Cultures of blood and cerebrospinal fluid (CSF) are indicated for patients with suspected invasive meningococcal disease. Cultures of a petechial or purpuric lesion scraping, synovial fluid, and other usually sterile body fluid specimens sometimes are positive. Specimens for culture should be plated onto both sheep blood and chocolate agar and incubated at 35°C to 37°C with 5% carbon dioxide in a moist atmosphere. The organism is readily identified with standard biochemical tests as well as by the newer method of mass spectrometry of bacterial cell components. Antimicrobial susceptibility testing of invasive isolates is useful because of the occurrence of b-lactamase–producing strains and fluoroquinolone-resistant strains (ciprofloxacin is one of the agents used for prophylaxis of close contacts; antimicrobial testing should not delay administration of prophylaxis). A Gram stain of a petechial or purpuric scraping, CSF, or buffy coat smear of blood may reveal gram-negative diplococci. Because N meningitidis can be a component of the nasopharyngeal flora, isolation of N meningitidis from this site is not helpful diagnostically. A serogroup-specific nucleic acid amplification test to detect N meningitidis from clinical specimens from usually sterile sites (eg, CSF) is useful particularly in patients who receive antimicrobial therapy before cultures are obtained. In the United States, commercially available multiplex polymerase chain reaction assays have excellent sensitivity and specificity for detection of serogroups A, B, C, W, X, and Y. Antigen detection tests, primarily by latex agglutination, to detect select meningococcal polysaccharide types in CSF were developed more than 3 decades ago. These assays no longer are commonly used in the United States because of concerns about test sensitivity and specificity.</p><small class='source'>Printed p. 556 · PDF p. 570</small><p>Surveillance case definitions for invasive meningococcal disease are provided in Table 87.1. Serologic typing and other characterization such as whole genome sequencing and genomic typing can be useful epidemiologic tools during a suspected outbreak to detect concordance among invasive strains.</p><small class='source'>Printed p. 556 · PDF p. 570</small></section><section><h2>Treatment</h2><p>The priority in management of meningococcal disease is treatment of shock in meningococcemia and of raised intracranial pressure in severe meningitis. Empirical therapy for suspected meningococcal disease should include cefotaxime or ceftriaxone. Once the microbiologic diagnosis is established, treatment options include cefotaxime, ceftriaxone, penicillin G, or ampicillin. A course of 5 to 7 days of antimicrobial therapy is adequate. Because of recent detections of b-lactamase– producing N meningitidis in the United States, meningococcal isolate susceptibility to penicillin should be determined before switching to penicillin or ampicillin.1 Ceftriaxone clears nasopharyngeal carriage effectively after 1 dose. For patients with a life-threatening penicillin allergy characterized by anaphylaxis, meropenem can be used with caution as the rate of cross-reactivity in penicillinallergic adults is very low. In meningococcemia, early and rapid fluid resuscitation and early use of inotropic and ventilatory support may reduce mortality. The postinfectious inflammatory syndromes associated with meningococcal disease often respond to nonsteroidal anti-inflammatory drugs. Treating physicians should consider evaluating for conditions that increase risk of disease, such as underlying complement component deficiencies. In some studies, underlying complement deficiency has been identified in up to 10% to 50% of patients with meningococcal disease, although no recent data are available on complement deficiency prevalence among U.S. patients with meningococcal disease.</p><small class='source'>Printed p. 556 · PDF p. 570</small></section><section><h2>Infection Prevention And Control Measures In Health Care Settings</h2><p>In addition to standard precautions, droplet precautions are recommended until 24 hours after initiation of effective antimicrobial therapy.</p><small class='source'>Printed p. 557 · PDF p. 571</small></section><section><h2>Control Measures</h2><p>Care of Exposed People Postexposure Chemoprophylaxis Regardless of immunization status, close contacts including household contacts of all people with invasive meningococcal disease (see Table 87.2), whether endemic or in an outbreak situation, are at high risk of infection and should promptly receive chemoprophylaxis. Chemoprophylaxis should be provided even if the close contact has received a meningococcal vaccine. The decision to administer chemoprophylaxis to other contacts is based on risk of contracting invasive disease related to specific exposure to the secretions from the infected patient. Throat and nasopharyngeal cultures are not recommended, because these cultures are of no value in deciding who should receive chemoprophylaxis.</p><small class='source'>Printed p. 557 · PDF p. 571</small><p>contacts of a person with invasive meningococcal disease, and Table 87.3 provides recommended prophylaxis regimens. Routine prophylaxis is not recommended for health care personnel unless they have had intimate exposure to respiratory tract secretions, such as occurs with unprotected mouth-to-mouth resuscitation, intubation, or suctioning before or less than 24 hours after antimicrobial therapy was initiated. Chemoprophylaxis ideally should be initiated within 24 hours after the index patient is identified; prophylaxis is not indicated if more than 2 weeks have passed since the last exposure. If antimicrobial agents other than ceftriaxone or cefotaxime (each of which will eradicate nasopharyngeal carriage) are used for treatment of invasive meningococcal disease, the index patient should receive chemoprophylaxis before hospital discharge to eradicate nasopharyngeal carriage of N meningitidis.</p><small class='source'>Printed p. 558 · PDF p. 572</small><p>Ciprofloxacin-resistant strains of N meningitidis have been detected over the past 17 years.2,3 Prophylaxis failures and antimicrobial resistance among meningococcal isolates should be monitored and reported to the local or state public health department to inform meningococcal prophylaxis recommendations. The Centers for Disease Control and Prevention has provided guidance on meningococcal disease prophylaxis in areas with ciprofloxacin resistance (see Table 87.4 and www. cdc.gov/meningococcal/outbreaks/changingprophylaxis-antibiotics.html).</p><small class='source'>Printed p. 558 · PDF p. 572</small><p>Meningococcal Vaccines In the United States, 3 meningococcal vaccines are licensed and available for use in children and adults against serogroups A, C, W, and Y (MenACWY), and 2 vaccines are licensed for people 10 through 25 years of age against serogroup B (MenB). All 3 MenACWY vaccines are proteinpolysaccharide conjugate vaccines, while the 2 MenB vaccines are protein-based vaccines using 2 different technologies. In addition, the U.S. Food and Drug Administration (FDA) licensed a MenABCWY pentavalent meningococcal vaccine on October 20, 2023, for persons 10 through 25 years of age; it is composed of Pfizer’s Trumenba (serogroup B) and Nimenrix (serogroups ACWY) vaccines. Tables 87.5 and 87.6 provide recommendations on meningococcal vaccines.</p><small class='source'>Printed p. 558 · PDF p. 572</small><p>Serogroup A, C, W, and Y Vaccines Meningococcal groups A, C, W, and Y polysaccharide diphtheria toxoid conjugate vaccine (MenACWY-D [Menactra]) is licensed for use in people 9 months through 55 years of age.</p><small class='source'>Printed p. 558 · PDF p. 572</small><p>2 days ≥15 y Single dose Single dose Cautions 90–95 90 Person remains at increased risk and first dose received at age:</p><small class='source'>Printed p. 559 · PDF p. 573</small><p>Recommended Immunization Schedule and Intervals for People at Increased Risk of Invasive Meningococcal Diseasea,b,c 2 through 23 mo of age 2 yf People who: • have persistent complement deficiencies • have functional or anatomic asplenia • have HIV infection For subgroup at increased risk:</p><small class='source'>Printed p. 561 · PDF p. 575</small><p>Meningococcal B Vaccines • are at risk during a community outbreak attributable to an A,C,W,Y vaccine serogroup • travel to or are residents of countries where meningococcal disease is hyperendemic or epidemic • college freshmen living in residence halls and military recruits • are laboratory workers routinely exposed to isolates of Neisseria meningitidis 2 yf People who:</p><small class='source'>Printed p. 562 · PDF p. 576</small><p>10 yg People who:</p><small class='source'>Printed p. 562 · PDF p. 576</small><p>• Other than outbreak: boosterg 1 year following completion of a MenB primary series followed by MenB booster every 2–3 years thereafter.d 1 year since completion of a MenB primary series (6 months interval might also be considered by public health officials).</p><small class='source'>Printed p. 562 · PDF p. 576</small><p>• For outbreak: boosterh if it has been • have persistent complement deficiencies (including complement inhibitor use) • have functional or anatomic asplenia • are laboratory workers routinely exposed to isolates of N meningitidis • are at increased risk, as determined by public health officials, because of a serogroup B meningococcal disease outbreak Meningococcal groups A, C, W, and Y oligosaccharide diphtheria CRM197 conjugate vaccine (MenACWY-CRM [Menveo]) is licensed for use in people 2 months through 55 years of age. Meningococcal groups A, C, W, and Y polysaccharide tetanus toxoid conjugate vaccine (MenACWY-TT [MenQuadfi]) is licensed for use in people 2 years and older. Each is administered intramuscularly as a 0.5-mL dose. Dosing during the primary series varies by product, age, and underlying risk for disease.</p><small class='source'>Printed p. 562 · PDF p. 576</small><p>Recommendations for use of MenACWY vaccine are as follows4 (Tables 87.5 and 87.6):</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• Adolescents should be immunized routinely with 1 dose at the 11- through 12-year health care visit (see https://redbook.solutions. aap.org/SS/Immunization_Schedules. aspx), when immunization status and other preventive health services can be addressed. A booster dose at 16 years of age is recommended for adolescents immunized at 11 through 12 years of age.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• Adolescents who receive their first dose at age 13 to 15 years should receive a booster dose at age 16 to 18 years; the booster dose can be administered at any time, as long as a minimum interval of 8 weeks between doses is maintained.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• Adolescents who receive a first dose after their 16th birthday do not need a booster dose unless they become at increased risk for meningococcal disease.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• People 19 to 21 years of age who have not received a dose after their 16th birthday can receive a single MenACWY dose as part of catch-up vaccination.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• Routine childhood immunization with meningococcal conjugate vaccines is not recommended for children 2 months through 10 years of age because of the low proportion of infections that are preventable with MenACWY vaccine.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• People at increased risk of invasive meningococcal disease (defined, by age, in the subgroup column of Table 87.6) should be immunized with a meningococcal conjugate vaccine beginning at 2 months of age. Table 87.6 also details dosing recommendations for each of the 3 MenACWY vaccines in these increased-risk populations.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• Because of their high risk for invasive pneumococcal disease, children with functional or anatomic asplenia or HIV infection should not be vaccinated with MenACWY-D (Menactra) before age 2 years to avoid interference with the immune response to pneumococcal conjugate vaccine; only MenACWY-CRM (Menveo) should be used in this group. MenACWY-TT (MenQuadfi) should not be used in this situation because it is only approved in children 2 years of age.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• When MenACWY-D (Menactra) is administered 30 days after diphtheria and tetanus toxoids and acellular pertussis (DTaP) vaccine, it interferes with the immune response to all four meningococcal serogroups. Therefore, MenACWY-D (Menactra) should be administered either before or at the same time as DTaP. Alternatively, Menveo or MenQuadfi (if 2 years of age) may be administered instead of Menactra.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>Serogroup B Meningococcal Vaccines MenB-FHbp (Trumenba) is based on a surfaceexposed lipoprotein named factor H binding protein (FHbp). MenB-FHbp can be administered as either a 2- or 3-dose series (0 and 6 months; or 0, 1–2, and 6 months), depending on risk factors for disease and on outbreak conditions (see Tables 87.5 and 87.6).</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>MenB-4C (Bexsero, GSK) contains 4 antigenic components: 1 FHbp fusion protein, NadA, NHBA fusion protein, and outer membrane vesicles. It is administered as a 2-dose series (0, 1 month [see Tables 87.5 and 87.6]).</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>Data on effectiveness against clinical disease end points and duration of protection for either vaccine in the age groups for which they are licensed in the United States are limited. Recommendations for use of a MenB vaccine are as follows5 (Tables 87.5 and 87.6):</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• People 10 years and older at increased risk for meningococcal disease should receive a MenB vaccine, using the same vaccine product for all doses in the vaccination series. Vaccination may further activate complement, and as a result, patients with complement-mediated diseases may experience increased symptoms of their underlying disease, such as hemolysis, following vaccination.</p><small class='source'>Printed p. 563 · PDF p. 577</small><p>• A MenB vaccine series may be considered for people 16 through 23 years of age on the basis of shared clinical decision-making (decided in the context of the provider-patient relationship and joint decision-making), with a preferred age at vaccination of 16 through 18 years. If MenB vaccine is elected to be administered, the same vaccine product should be used for all doses. MenB vaccine may be administered with other vaccines at the same visit but at a different injection site.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>Serogroup A, B, C, W, and Y Meningococcal Vaccine A pentavalent meningococcal vaccine composed of Pfizer’s Trumenba (serogroup B) and Nimenrix (serogroups ACWY) vaccines was licensed by the FDA on October 20, 2023, for persons 10 through 25 years of age. It may be used when both MenACWY and MenB are indicated at the same visit for: 1) healthy individuals aged 16 through 23 years of age (routine schedule) when shared clinical decision-making favors administration of MenB vaccination; or 2) individuals aged 10 years and older at increased risk of meningococcal disease (eg, because of persistent complement deficiencies, complement inhibitor use, or functional or anatomic asplenia) for whom both vaccines are due. The licensed B component vaccines are not interchangeable by manufacturer. Administration of a B component vaccine (MenB or MenABCWY) requires that subsequent B component vaccine doses be from the same manufacturer. The minimum interval for Pfizer’s MenABCWY vaccine is 6 months. Individuals at increased risk of meningococcal disease who are recommended to receive additional doses of MenACWY and MenB less than 6 months after a dose of pentavalent meningococcal vaccine should instead receive separate MenACWY and MenB-FHbp vaccines.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>Immunization During Eculizumab Therapy6 Use of complement inhibitors (eg, eculizumab [Soliris] and its long-acting derivative ravulizumab [Ultomiris]; monoclonal antibody therapies that block C5) is associated with a substantially increased risk for meningococcal disease. Eculizumab use is associated with an approximately 2,000-fold increased incidence of meningococcal disease. Eculizumab and ravulizumab recipients should receive both MenACWY and MenB vaccines. Because these monoclonal antibodies inhibit terminal complement activation and opsonophagocytic killing of meningococci, patients receiving them are still at risk for invasive meningococcal disease even if they develop antibodies following vaccination. Providers, therefore, should also consider antimicrobial prophylaxis (usually penicillin prophylaxis) for the duration of eculizumab or ravulizumab treatment and until immunocompetence is restored once the monoclonal antibody therapy is stopped, to potentially reduce the risk for meningococcal disease.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>Reimmunization/Booster Doses Children previously immunized with a meningococcal conjugate vaccine (ACWY or B) who are at ongoing increased risk for meningococcal disease should receive booster immunizations (see Table 87.6). If a child was vaccinated with MenACWY vaccine because of an outbreak or travel at &lt;10 years of age, the adolescent doses are still needed. For MenB vaccine, the same vaccine product used in the primary series should be used for booster doses.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>Immunization During Outbreaks During an outbreak, additional cases can occur several weeks or more after onset of disease in the index case; therefore, meningococcal vaccine is recommended when an outbreak is caused by a serogroup prevented by a meningococcal vaccine.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>Adverse Events Common adverse events after quadrivalent meningococcal conjugate vaccines include pain, erythema, and swelling at the injection site; headache; fatigue; and irritability. Similar adverse effects are observed after MenB vaccines, although effects are more common and may be more severe, and often include myalgia. Syncope can occur after any vaccination and is most common among adolescents and young adults. Adolescents should be seated or lying down during vaccination and ideally remain that way for at least 15 minutes after immunization to avert syncopal episodes and secondary injuries.</p><small class='source'>Printed p. 564 · PDF p. 578</small><p>If syncope develops, patients should be observed until symptoms resolve.7 Syncope following receipt of a vaccine is not a contraindication to subsequent doses.</p><small class='source'>Printed p. 565 · PDF p. 579</small><p>Pregnant People8 Pregnant and lactating people should receive MenACWY vaccine if indicated. Because limited data are available for MenB vaccination during pregnancy, vaccination with MenB should be deferred unless the person is at increased risk and, after consultation with their health care provider, the benefits of vaccination are considered to outweigh the potential risks.</p><small class='source'>Printed p. 565 · PDF p. 579</small><p>Counseling and Public Education When a case of invasive meningococcal disease is detected, the physician should provide accurate and timely information about meningococcal disease and the risk of transmission to families and contacts of the infected person and provide or arrange for chemoprophylaxis (which may be accomplished together with the public health department). Some experts recommend that all patients with invasive meningococcal disease be evaluated for a complement component deficiency; screening can be accomplished with inexpensive CH50 and AH50 testing. If a specific complement component deficiency is detected, patients should receive a MenACWY vaccine series if 2 months or older and a MenB series if 10 years or older. Patients and parents should be counseled about the risk of recurrent invasive meningococcal disease and the need for immediate medical evaluation when fever develops. Patients on eculizumab or ravulizumab or with other complement deficiencies should be counseled about the risk of invasive infection. Public health questions, such as whether a mass immunization program or an expanded chemoprophylaxis program is needed, should be referred to the local or state public health department. In appropriate situations, early provision of information in collaboration with the health department to schools or affected groups and to the media may help minimize public anxiety and unrealistic or inappropriate demands for intervention.</p><small class='source'>Printed p. 565 · PDF p. 579</small><p>Public Health Reporting All confirmed, suspected, and probable cases of invasive meningococcal disease (see Table 87.1) must be immediately reported to the appropriate public health department. Meningococcal disease is a nationally notifiable condition. Timely reporting can facilitate early administration of chemoprophylaxis to close contacts, recognition and containment of outbreaks, and characterization of isolates so that appropriate prevention recommendations can be implemented rapidly.</p><small class='source'>Printed p. 565 · PDF p. 579</small></section><h2>Original tables</h2><figure><img loading='lazy' src='tables/ch087_p0573_1.jpg' alt='Original table on printed page 559'><figcaption>Original table · printed p. 559</figcaption></figure><figure><img loading='lazy' src='tables/ch087_p0574_1.jpg' alt='Original table on printed page 560'><figcaption>Original table · printed p. 560</figcaption></figure><figure><img loading='lazy' src='tables/ch087_p0575_1.jpg' alt='Original table on printed page 561'><figcaption>Original table · printed p. 561</figcaption></figure><figure><img loading='lazy' src='tables/ch087_p0576_1.jpg' alt='Original table on printed page 562'><figcaption>Original table · printed p. 562</figcaption></figure><h2>Visual atlas</h2><figure><a href='figures/ch087_p0580_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0580_01.jpg' alt='Image 87.1 Young boy with meningococcemia that demonstrates striking involvement of the extremities with sparing of the trunk. Copyright Martin G. Myers, MD.'></a><figcaption>Image 87.1 Young boy with meningococcemia that demonstrates striking involvement of the extremities with sparing of the trunk. Copyright Martin G. Myers, MD.<br><small>Printed p. 566 · PDF p. 580</small></figcaption></figure><figure><a href='figures/ch087_p0580_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0580_02.jpg' alt='Image 87.2 The arm of the boy shown in Image 87.1, which demonstrates striking extremity involvement and characteristic angular lesions. Copyright Martin G. Myers, MD.'></a><figcaption>Image 87.2 The arm of the boy shown in Image 87.1, which demonstrates striking extremity involvement and characteristic angular lesions. Copyright Martin G. Myers, MD.<br><small>Printed p. 566 · PDF p. 580</small></figcaption></figure><figure><a href='figures/ch087_p0580_03.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0580_03.jpg' alt='Image 87.3 Meningococcemia showing striking involvement of the extremities with relative sparing of the skin of the child’s body surface.'></a><figcaption>Image 87.3 Meningococcemia showing striking involvement of the extremities with relative sparing of the skin of the child’s body surface.<br><small>Printed p. 566 · PDF p. 580</small></figcaption></figure><figure><a href='figures/ch087_p0580_04.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0580_04.jpg' alt='Image 87.4 Meningococcemia. This image shows the lower extremities of the patient in Image 87.3.'></a><figcaption>Image 87.4 Meningococcemia. This image shows the lower extremities of the patient in Image 87.3.<br><small>Printed p. 566 · PDF p. 580</small></figcaption></figure><figure><a href='figures/ch087_p0581_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0581_01.jpg' alt='Image 87.5 Papular skin lesions of early meningococcemia.'></a><figcaption>Image 87.5 Papular skin lesions of early meningococcemia.<br><small>Printed p. 567 · PDF p. 581</small></figcaption></figure><figure><a href='figures/ch087_p0581_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0581_02.jpg' alt='Image 87.6 Characteristic, angular, necrotic lesions on the foot of an infant boy with meningococcemia (after 2 days of intravenous penicillin treatment).'></a><figcaption>Image 87.6 Characteristic, angular, necrotic lesions on the foot of an infant boy with meningococcemia (after 2 days of intravenous penicillin treatment).<br><small>Printed p. 567 · PDF p. 581</small></figcaption></figure><figure><a href='figures/ch087_p0581_03.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0581_03.jpg' alt='Image 87.7 Preschool-aged girl with meningococcal panophthalmitis. An infant sibling had meningococcal meningitis 1 week before the onset of this child’s illness.'></a><figcaption>Image 87.7 Preschool-aged girl with meningococcal panophthalmitis. An infant sibling had meningococcal meningitis 1 week before the onset of this child’s illness.<br><small>Printed p. 567 · PDF p. 581</small></figcaption></figure><figure><a href='figures/ch087_p0581_04.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0581_04.jpg' alt='Image 87.8 Meningococcemia in an adolescent girl with disseminated intravascular coagulation.'></a><figcaption>Image 87.8 Meningococcemia in an adolescent girl with disseminated intravascular coagulation.<br><small>Printed p. 567 · PDF p. 581</small></figcaption></figure><figure><a href='figures/ch087_p0581_05.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0581_05.jpg' alt='Image 87.9 Meningococcemia in the same patient as in Image 87.8.'></a><figcaption>Image 87.9 Meningococcemia in the same patient as in Image 87.8.<br><small>Printed p. 567 · PDF p. 581</small></figcaption></figure><figure><a href='figures/ch087_p0582_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0582_01.jpg' alt='Image 87.11 Gangrene of the toes in the patient shown in Images 87.8–87.10.'></a><figcaption>Image 87.11 Gangrene of the toes in the patient shown in Images 87.8–87.10.<br><small>Printed p. 568 · PDF p. 582</small></figcaption></figure><figure><a href='figures/ch087_p0582_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0582_02.jpg' alt='Image 87.12 Cutaneous necrosis in the patient shown in Images 87.8–87.11.'></a><figcaption>Image 87.12 Cutaneous necrosis in the patient shown in Images 87.8–87.11.<br><small>Printed p. 568 · PDF p. 582</small></figcaption></figure><figure><a href='figures/ch087_p0582_03.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0582_03.jpg' alt='Image 87.13 A 2-year-old boy with acute meningococcemia with septic shock and purpura fulminans. Courtesy of George Nankervis, MD.'></a><figcaption>Image 87.13 A 2-year-old boy with acute meningococcemia with septic shock and purpura fulminans. Courtesy of George Nankervis, MD.<br><small>Printed p. 568 · PDF p. 582</small></figcaption></figure><figure><a href='figures/ch087_p0582_04.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0582_04.jpg' alt='Image 87.10 Marked purpura of the left foot in the patient shown in Images 87.8 and 87.9.'></a><figcaption>Image 87.10 Marked purpura of the left foot in the patient shown in Images 87.8 and 87.9.<br><small>Printed p. 568 · PDF p. 582</small></figcaption></figure><figure><a href='figures/ch087_p0583_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0583_01.jpg' alt='Image 87.14 Hemorrhagic adrenal glands from the 2-year-old child in Image 87.13, who had the characteristic histopathologic features of Waterhouse-Friderichsen syndrome at autopsy. Courtesy of George Nankervis, MD.'></a><figcaption>Image 87.14 Hemorrhagic adrenal glands from the 2-year-old child in Image 87.13, who had the characteristic histopathologic features of Waterhouse-Friderichsen syndrome at autopsy. Courtesy of George Nankervis, MD.<br><small>Printed p. 569 · PDF p. 583</small></figcaption></figure><figure><a href='figures/ch087_p0583_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0583_02.jpg' alt='Image 87.15 Adrenal hemorrhage in a patient with gram-negative sepsis, a major complication of meningococcal disease with increased mortality. Courtesy of Dimitris P. Agamanolis, MD.'></a><figcaption>Image 87.15 Adrenal hemorrhage in a patient with gram-negative sepsis, a major complication of meningococcal disease with increased mortality. Courtesy of Dimitris P. Agamanolis, MD.<br><small>Printed p. 569 · PDF p. 583</small></figcaption></figure><figure><a href='figures/ch087_p0583_03.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0583_03.jpg' alt='Image 87.16 Fatal meningococcal meningitis with purulent exudate in the subarachnoid space covering the cerebral convexities. Courtesy of Dimitris P. Agamanolis, MD.'></a><figcaption>Image 87.16 Fatal meningococcal meningitis with purulent exudate in the subarachnoid space covering the cerebral convexities. Courtesy of Dimitris P. Agamanolis, MD.<br><small>Printed p. 569 · PDF p. 583</small></figcaption></figure><figure><a href='figures/ch087_p0584_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0584_01.jpg' alt='Image 87.17 Suppurative meningococcal meningitis. The subarachnoid space is filled with neutrophils. Courtesy of Dimitris P. Agamanolis, MD.'></a><figcaption>Image 87.17 Suppurative meningococcal meningitis. The subarachnoid space is filled with neutrophils. Courtesy of Dimitris P. Agamanolis, MD.<br><small>Printed p. 570 · PDF p. 584</small></figcaption></figure><figure><a href='figures/ch087_p0584_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0584_02.jpg' alt='Image 87.18 Petechial rash with a necrotic lesion over the right buttock of an infant girl with Neisseria meningitidis septicemia and meningitis. Courtesy of Ed Fajardo, MD.'></a><figcaption>Image 87.18 Petechial rash with a necrotic lesion over the right buttock of an infant girl with Neisseria meningitidis septicemia and meningitis. Courtesy of Ed Fajardo, MD.<br><small>Printed p. 570 · PDF p. 584</small></figcaption></figure><figure><a href='figures/ch087_p0584_03.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0584_03.jpg' alt='Image 87.19 This micrograph depicts the presence of aerobic gram-negative Neisseria meningitidis diplococcal bacteria (magnification 31,150). Meningococcal disease is an infection caused by a bacterium called N meningitidis or meningococcus. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 87.19 This micrograph depicts the presence of aerobic gram-negative Neisseria meningitidis diplococcal bacteria (magnification 31,150). Meningococcal disease is an infection caused by a bacterium called N meningitidis or meningococcus. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 570 · PDF p. 584</small></figcaption></figure><figure><a href='figures/ch087_p0585_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0585_01.jpg' alt='Image 87.21 Incidence rates (per 100,000 people) of meningococcal disease caused by serogroup B compared with those of serogroups C, W, and Y by age group from 2012 to 2021. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 87.21 Incidence rates (per 100,000 people) of meningococcal disease caused by serogroup B compared with those of serogroups C, W, and Y by age group from 2012 to 2021. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 571 · PDF p. 585</small></figcaption></figure><figure><a href='figures/ch087_p0585_02.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0585_02.jpg' alt='Image 87.20 Incidence rates (per 100,000 people) of meningococcal disease in the United States by year from 1970 to 2019. The incidence rate began decreasing in 1995 and has remained low in 2019. Courtesy of Centers for Disease Control and Prevention.'></a><figcaption>Image 87.20 Incidence rates (per 100,000 people) of meningococcal disease in the United States by year from 1970 to 2019. The incidence rate began decreasing in 1995 and has remained low in 2019. Courtesy of Centers for Disease Control and Prevention.<br><small>Printed p. 571 · PDF p. 585</small></figcaption></figure><figure><a href='figures/ch087_p0586_01.jpg' target='_blank'><img loading='lazy' src='figures/ch087_p0586_01.jpg' alt='Image 87.22 Neisseria meningitidis on chocolate agar. Isolation of this species requires chocolate or Thayer-Martin agar. Colonies are gray-brown and can appear moist to mucoid or dry. N meningitidis can be distinguished from Neisseria gonorrhoeae by the fact that it ferments glucose and maltose. Courtesy of Julia Rosebush, DO; Robert Jerris, PhD; and Theresa Stanley, M(ASCP).'></a><figcaption>Image 87.22 Neisseria meningitidis on chocolate agar. Isolation of this species requires chocolate or Thayer-Martin agar. Colonies are gray-brown and can appear moist to mucoid or dry. N meningitidis can be distinguished from Neisseria gonorrhoeae by the fact that it ferments glucose and maltose. Courtesy of Julia Rosebush, DO; Robert Jerris, PhD; and Theresa Stanley, M(ASCP).<br><small>Printed p. 572 · PDF p. 586</small></figcaption></figure>"});
